module subsequence_counter (input clk, input rst_n, input start, input [15:0] a00, a01, a10, a11, output done, output valid, output [15:0] length, input [7:0] result_index, output result_bit); reg [7:0] n0, n1; reg [63:0] constructed_str; reg [15:0] str_len; reg [2:0] state; reg valid_out, done_out; reg [7:0] current_pos; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin n0 <= 8'b0; n1 <= 8'b0; constructed_str <= 64'b0; str_len <= 16'b0; state <= 3'b000; valid_out <= 1'b0; done_out <= 1'b0; current_pos <= 8'b0; end else begin case (state) 3'b000: begin if (start) state <= 3'b001; end 3'b001: begin n0 <= 8'b000; n1 <= 8'b000; state <= 3'b010; end 3'b010: begin if (n0 * n1 == a01 + a10) begin valid_out <= 1'b1; state <= 3'b011; end else begin valid_out <= 1'b0; state <= 3'b100; end end 3'b011: begin constructed_str <= {n0 + n1 {1'b0}}; str_len <= n0 + n1; valid_out <= 1'b1; done_out <= 1'b1; state <= 3'b100; end 3'b100: state <= 3'b100; endcase end end assign done = done_out; assign valid = valid_out; assign length = str_len; assign result_bit = constructed_str[result_index]; endmodule